import{_ as l,W as o,s as d,u as r,I as a,ah as n,w as i,Z as t,A as p}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const C=JSON.parse('{"title":"5 个用命令行操作 LibreOffice 的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"5 个用命令行操作 LibreOffice 的技巧 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"5 个用命令行操作 LibreOffice 的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 个用命令行操作 LibreOffice 的技巧 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210305 5 surprising things you can do with LibreOffice from the command line","title":"5 个用命令行操作 LibreOffice 的技巧","tag":"202103"},"relativePath":"202103/20210305 5 surprising things you can do with LibreOffice from the command line.md","filePath":"[post].md"}'),c={name:"202103/20210305 5 surprising things you can do with LibreOffice from the command line.md"};function f(b,e,h,u,g,m){const s=o("Link");return r(),d("div",null,[e[24]||(e[24]=a("h1",{id:"_5-个用命令行操作-libreoffice-的技巧",tabindex:"-1"},[i("5 个用命令行操作 LibreOffice 的技巧 "),a("a",{class:"header-anchor",href:"#_5-个用命令行操作-libreoffice-的技巧","aria-label":"Permalink to 5 个用命令行操作 LibreOffice 的技巧"},"​")],-1)),e[25]||(e[25]=a("blockquote",null,[a("p",null,"直接在命令行中对文件进行转换、打印、保护等操作。")],-1)),e[26]||(e[26]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202103/20/110200xjkkijnjixbyi4ui.jpg",alt:""})],-1)),a("p",null,[e[1]||(e[1]=i("LibreOffice 拥有所有你想要的办公软件套件的生产力功能，使其成为微软 Office 或谷歌套件的流行的开源替代品。LibreOffice 的能力之一是可以从命令行操作。例如，Seth Kenlon 最近解释了如何使用 LibreOffice 用全局 ")),t(s,{href:"https://opensource.com/article/21/2/linux-workday"},{default:p(()=>e[0]||(e[0]=[i("命令行选项将多个文件")])),_:1}),e[2]||(e[2]=i(" 从 DOCX 转换为 EPUB。他的文章启发我分享一些其他 LibreOffice 命令行技巧和窍门。"))]),e[27]||(e[27]=n(`<p>在查看 LibreOffice 命令的一些隐藏功能之前，你需要了解如何使用应用选项。并不是所有的应用都接受选项（除了像 <code>--help</code> 选项这样的基本选项，它在大多数 Linux 应用中都可以使用）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --help</span></span></code></pre></div><p>这将返回 LibreOffice 接受的其他选项的描述。有些应用没有太多选项，但 LibreOffice 好几页有用的选项，所以有很多东西可以玩。</p><p>就是说，你可以在终端上使用 LibreOffice 进行以下五项有用的操作，来让使软件更加有用。</p><h3 id="_1、自定义你的启动选项" tabindex="-1">1、自定义你的启动选项 <a class="header-anchor" href="#_1、自定义你的启动选项" aria-label="Permalink to 1、自定义你的启动选项">​</a></h3><p>你可以修改你启动 LibreOffice 的方式。例如，如果你想只打开 LibreOffice 的文字处理器组件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --writer  # 启动文字处理器</span></span></code></pre></div><p>你可以类似地打开它的其他组件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --calc  # 启动一个空的电子表格</span></span>
<span class="line"><span>$ libreoffice --draw  # 启动一个空的绘图文档</span></span>
<span class="line"><span>$ libreoffice --web   # 启动一个空的 HTML 文档</span></span></code></pre></div><p>你也可以从命令行访问特定的帮助文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --helpwriter</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/libreoffice-help.png" alt="LibreOffice Writer help" title="LibreOffice Writer help"></p><p>或者如果你需要电子表格应用方面的帮助：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --helpcalc</span></span></code></pre></div><p>你可以在不显示启动屏幕的情况下启动 LibreOffice：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --writer --nologo</span></span></code></pre></div><p>你甚至可以在你完成当前窗口的工作时，让它在后台最小化启动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --writer --minimized</span></span></code></pre></div><h3 id="_2、以只读模式打开一个文件" tabindex="-1">2、以只读模式打开一个文件 <a class="header-anchor" href="#_2、以只读模式打开一个文件" aria-label="Permalink to 2、以只读模式打开一个文件">​</a></h3><p>你可以使用 <code>--view</code> 以只读模式打开文件，以防止意外地对重要文件进行修改和保存：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --view example.odt</span></span></code></pre></div><h3 id="_3、打开一个模板文档" tabindex="-1">3、打开一个模板文档 <a class="header-anchor" href="#_3、打开一个模板文档" aria-label="Permalink to 3、打开一个模板文档">​</a></h3><p>你是否曾经创建过用作信头或发票表格的文档？LibreOffice 具有丰富的内置模板系统，但是你可以使用 <code>-n</code> 选项将任何文档作为模板：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --writer -n example.odt</span></span></code></pre></div><p>你的文档将在 LibreOffice 中打开，你可以对其进行修改，但保存时不会覆盖原始文件。</p><h3 id="_4、转换文档" tabindex="-1">4、转换文档 <a class="header-anchor" href="#_4、转换文档" aria-label="Permalink to 4、转换文档">​</a></h3><p>当你需要做一个小任务，比如将一个文件转换为新的格式时，应用启动的时间可能与完成任务的时间一样长。解决办法是 <code>--headless</code> 选项，它可以在不启动图形用户界面的情况下执行 LibreOffice 进程。</p><p>例如，在 LibreOffic 中，将一个文档转换为 EPUB 是一个非常简单的任务，但使用 <code>libreoffice</code> 命令就更容易：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --headless --convert-to epub example.odt</span></span></code></pre></div><p>使用通配符意味着你可以一次转换几十个文档：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --headless --convert-to epub *.odt</span></span></code></pre></div><p>你可以将文件转换为多种格式，包括 PDF、HTML、DOC、DOCX、EPUB、纯文本等。</p><h3 id="_5、从终端打印" tabindex="-1">5、从终端打印 <a class="header-anchor" href="#_5、从终端打印" aria-label="Permalink to 5、从终端打印">​</a></h3><p>你可以从命令行打印 LibreOffice 文档，而无需打开应用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --headless -p example.odt</span></span></code></pre></div><p>这个选项不需要打开 LibreOffice 就可以使用默认打印机打印，它只是将文档发送到你的打印机。</p><p>要打印一个目录中的所有文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice -p *.odt</span></span></code></pre></div><p>（我不止一次执行了这个命令，然后用完了纸，所以在你开始之前，确保你的打印机里有足够的纸张。）</p><p>你也可以把文件输出成 PDF。通常这和使用 <code>--convert-to-pdf</code> 选项没有什么区别，但是很容易记住：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ libreoffice --print-to-file example.odt --headless</span></span></code></pre></div><h3 id="额外技巧-flatpak-和命令选项" tabindex="-1">额外技巧：Flatpak 和命令选项 <a class="header-anchor" href="#额外技巧-flatpak-和命令选项" aria-label="Permalink to 额外技巧：Flatpak 和命令选项">​</a></h3>`,42)),a("p",null,[e[4]||(e[4]=i("如果你是使用 ")),t(s,{href:"https://www.libreoffice.org/download/flatpak/"},{default:p(()=>e[3]||(e[3]=[i("Flatpak")])),_:1}),e[5]||(e[5]=i(" 安装的 LibreOffice，所有这些命令选项都可以使用，但你必须通过 Flatpak 传递。下面是一个例子："))]),e[28]||(e[28]=n('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ flatpak run org.libreoffice.LibreOffice --writer</span></span></code></pre></div>',1)),a("p",null,[e[7]||(e[7]=i("它比本地安装要麻烦得多，所以你可能会受到启发 ")),t(s,{href:"https://opensource.com/article/19/7/bash-aliases"},{default:p(()=>e[6]||(e[6]=[i("写一个 Bash 别名")])),_:1}),e[8]||(e[8]=i(" 来使它更容易直接与 LibreOffice 交互。"))]),e[29]||(e[29]=n('<h3 id="令人惊讶的终端选项" tabindex="-1">令人惊讶的终端选项 <a class="header-anchor" href="#令人惊讶的终端选项" aria-label="Permalink to 令人惊讶的终端选项">​</a></h3><p>通过查阅手册页面，了解如何从命令行扩展 LibreOffice 的功能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ man libreoffice</span></span></code></pre></div><p>你是否知道 LibreOffice 具有如此丰富的命令行选项？ 你是否发现了其他人似乎都不了解的其他选项？ 请在评论中分享它们！</p><hr>',5)),a("p",null,[e[10]||(e[10]=i("via: ")),t(s,{href:"https://opensource.com/article/21/3/libreoffice-command-line"},{default:p(()=>e[9]||(e[9]=[i("https://opensource.com/article/21/3/libreoffice-command-line")])),_:1})]),a("p",null,[e[15]||(e[15]=i("作者：")),t(s,{href:"https://opensource.com/users/don-watkins"},{default:p(()=>e[11]||(e[11]=[i("Don Watkins")])),_:1}),e[16]||(e[16]=i(" 选题：")),t(s,{href:"https://github.com/lujun9972"},{default:p(()=>e[12]||(e[12]=[i("lujun9972")])),_:1}),e[17]||(e[17]=i(" 译者：")),t(s,{href:"https://github.com/geekpi"},{default:p(()=>e[13]||(e[13]=[i("geekpi")])),_:1}),e[18]||(e[18]=i(" 校对：")),t(s,{href:"https://github.com/wxy"},{default:p(()=>e[14]||(e[14]=[i("wxy")])),_:1})]),a("p",null,[e[21]||(e[21]=i("本文由 ")),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>e[19]||(e[19]=[i("LCTT")])),_:1}),e[22]||(e[22]=i(" 原创编译，")),t(s,{href:"https://linux.cn/"},{default:p(()=>e[20]||(e[20]=[i("Linux中国")])),_:1}),e[23]||(e[23]=i(" 荣誉推出"))])])}const L=l(c,[["render",f]]);export{C as __pageData,L as default};
